def user_preferences_object(self) -> str:
    return json.dumps({
        "theme": self._rng.choice(["light", "dark"]),
        "language": self._rng.choice(["en", "es", "fr", "de"]),
        "notifications": self._rng.random() < 0.5,
    })

def tweet_with_hashtags(self, hashtag_count: int = 2) -> str:
    tags = " ".join(self.hashtag() for _ in range(hashtag_count))
    return f"{self.tweet_text(240)} {tags}"

def stripe_address(self, country: str = "US") -> dict:
    return {
        "line1": self._fake.street_address(),
        "city": self._fake.city(),
        "state": self._fake.state_abbr(),
        "postal_code": self._fake.postcode(),
        "country": country,
    }
